# -*- coding: utf-8 -*-
import base64, struct, zlib, sys
sys.stdout.reconfigure(encoding='utf-8')

def b64d(s):
    s = s.strip()
    return base64.b64decode(s + '=' * (-len(s) % 4))

def try_decompress(raw):
    for wbits in (zlib.MAX_WBITS, -zlib.MAX_WBITS, 16 + zlib.MAX_WBITS, 0):
        try: return zlib.decompress(raw, wbits)
        except Exception: pass
    return raw

data = """
43414769426c594b42676978366745514b416f47434c66714152414b436767496b4534597534374658676f47434a4e4f474f344645676749417844644478695055696f534349485f5f5f5f5f5f5f5f5f5f77455173756f42474e41506f67595443503649763951474550364976395147474f6f504941676f47773d3d
43414769426c594b42676978366745514b416f47434c66714152414b436767496b4534597070544658676f47434a4e4f474f734645676749417844644478693656436f534349485f5f5f5f5f5f5f5f5f5f77455173756f42474e41506f675954434b714c76395147454b714c76395147474f6f504941676f47773d3d
43414769426c594b42676978366745514b416f47434c66714152414b436767496b4534596c4a724658676f47434a4e4f474f3446456767494178446444786a6d56696f534349485f5f5f5f5f5f5f5f5f5f77455173756f42474e41506f675954434e614e76395147454e614e76395147474f6f504941676f47773d3d"""

for i, line in enumerate(data.strip().split('\n')):
    raw = b64d(line)
    print(f"\n=== Frame {i} raw_len={len(raw)} ===")
    dec = try_decompress(raw)
    print(f"dec_len={len(dec)} dec_hex={dec[:50].hex()}")
    if len(dec) >= 2:
        mid = struct.unpack('<H', dec[:2])[0]
        print(f"mid={mid}")
